      principalName: "Avery Chen",
      scope: { id: "scope-platform", name: "Platform Engineering" },
    },
  },
};

describe("ConsoleApplication", () => {
  beforeEach(async () => {
    localStorage.clear();
    document.documentElement.lang = "";
    await consoleI18n.changeLanguage("en-US");
  });

  afterEach(() => {
    cleanup();
  });

  it("persists an authenticated language selection before applying it to the Console", async () => {
    const sessionAdapter = {
      readConsoleSession: vi.fn().mockResolvedValue(authenticatedSession),
      saveConsoleLocale: vi.fn().mockResolvedValue(true),
    };

